// ---- A desert observatory ridge under a wheeling night sky: two domes stand black against the
// Milky Way, the whole star field turns slowly about the celestial pole so nothing is ever still,
// airglow banks along the horizon, and a dome slit breathes a thread of red. Motion is the sky's
// own rotation — monotonic, incommensurate, it never re-phases. ----
const u = Math.min(width, height);
const hu = h => ((h % 360) + 360) % 360;
const fr = i => { let h = (Math.imul(i|0, 374761393) + Math.imul(P.seed|0, 2246822519) + 3266489917) | 0; h = Math.imul(h ^ (h >>> 15), 2246822519); return ((h ^ (h >>> 13)) >>> 0) / 4294967295; };
const L3 = (a, b, f) => [a[0] + (b[0]-a[0])*f, a[1] + (b[1]-a[1])*f, a[2] + (b[2]-a[2])*f];
const ho = P.hue - 220;

const STY = {
  // deep cold night, blue-white stars
  starfield: { zen:[228,72,13], hor:[214,44,30], air:[150,48,38], mw:[208,28,64], core:[210,30,72], star:[210,14,100], dome:[220,40,9], chart:0, thermal:0, ink:0 },
