  milkyway:  { zen:[248,70,15], hor:[300,34,30], air:[190,42,36], mw:[276,32,64], core:[32,56,84], star:[40,12,100], dome:[262,40,9], chart:0, thermal:0, ink:0 },
  // brighter moonlit sky, fewer stars, domes catch silver light
  moonlit:   { zen:[220,54,24], hor:[210,30,40], air:[200,26,42], mw:[210,16,54], core:[208,18,62], star:[205,10,100], dome:[214,26,17], chart:0, thermal:0, ink:0 },
  // ABSTRACTED star chart: cyan grid + magnitude rings on a survey-navy
  chart:     { zen:[212,78,15], hor:[204,50,24], air:[186,58,30], mw:[188,50,38], core:[184,42,52], star:[184,70,100], dome:[204,50,13], chart:1, thermal:0, ink:0 },
  // ABSTRACTED ink nocturne: warm-grey wash, stars as ink points
  ink:       { zen:[220,10,22], hor:[36,10,36], air:[60,10,36], mw:[210,8,52], core:[36,10,60], star:[40,6,96], dome:[220,8,11], chart:0, thermal:0, ink:1 }
};
const st = STY[P.style] || STY.starfield;
const zen = [hu(st.zen[0]+ho), st.zen[1], st.zen[2]];
const en = Math.max(0, Math.min(1, P.energy));
const ridgeY = height * P.y;
const key = [width, height, P.style, P.seed, Math.round(P.hue), P.scale.toFixed(2), P.density.toFixed(2), P.y.toFixed(3), P.haze.toFixed(2)].join('|');

if (!S.sky || S.key !== key) {
  if (S.sky) S.sky.remove();
  const W = Math.max(2, Math.ceil(width)), H = Math.max(2, Math.ceil(height));
  S.sky = createGraphics(W, H); S.sky.colorMode(S.sky.HSB, 360, 100, 100, 100); S.sky.noStroke();
  const g = S.sky; const hor = [hu(st.hor[0]+ho), st.hor[1], st.hor[2]], air = [hu(st.air[0]+ho), st.air[1], st.air[2]];
  for (let yy = 0; yy < H; yy++) {
    let c;
    if (yy < ridgeY) { const f = Math.pow(Math.min(1, yy/Math.max(1,ridgeY)), .8); c = L3(hor, zen, f); const ab = Math.exp(-Math.abs(yy - ridgeY*.86)/(H*.10)) * P.haze * .9; c = L3(c, air, ab); }
