    g.fill(c[0], c[1], c[2]); g.rect(0, yy, W, 1);
  }
  // precompute stars in polar coords about the pole (rotated live)
  S.stars = []; const nStar = Math.round((160 + P.density*320));
  for (let i = 0; i < nStar; i++) { const th = fr(i*3)*6.2832; const rr = Math.sqrt(fr(i*3+1))*1.15; const mag = Math.pow(fr(i*3+2), 2.4); S.stars.push({ th, rr, mag, ph: fr(i*3+3)*6.28, tw: .3+fr(i*3+4)*.7 }); }
  // milky way blobs along a band
  S.mw = []; for (let i = 0; i < 46; i++) { const t0 = i/45; S.mw.push({ t0, off: (fr(i*5+40)-.5)*.5, sz: .5+fr(i*5+41)*.9, dust: fr(i*5+42) }); }
  S.key = key;
}

// ---------------- draw sky ----------------
noStroke(); image(S.sky, 0, 0);

const poleX = width*P.x, poleY = ridgeY - u*.55;      // celestial pole (below-ish horizon for a nice arc)
const R = Math.hypot(width, height)*.62;
const rot = K.t * (0.010 + 0.006*P.speed) + 0.02*Math.sin(K.t*.013);   // slow monotonic wheel + gentle wobble

// milky way band, rotating with the sky
const mwC = [hu(st.mw[0]+ho), st.mw[1], st.mw[2]], coreC = [hu(st.core[0]+ho), st.core[1], st.core[2]];
push(); translate(poleX, poleY); rotate(rot*1.0 + 2.2);
blendMode(st.ink?BLEND:ADD);
for (let i = 0; i < S.mw.length; i++) { const m = S.mw[i]; const bx = (m.t0-.5)*R*2.4; const by = m.off*R*.5 + Math.sin(m.t0*6+K.t*.05)*R*.03; const nearCore = 1 - Math.abs(m.t0-.5)*1.6; const c = L3(mwC, coreC, Math.max(0,nearCore)); const sz = R*(.10+m.sz*.10)*P.scale*(0.7+nearCore*0.6); for (let k = 2; k >= 0; k--) { fill(c[0], c[1]*(.8-k*.1), c[2], (2.4+3*en)*(1-k*.25)*(0.5+P.haze*.7)*(0.5+nearCore*.7)); ellipse(bx, by, sz*(1+k*.7), sz*(.5+k*.3)); } if (m.dust > .55 && !st.chart) { fill(zen[0], zen[1], 2, 20*(0.4+P.haze)); ellipse(bx+(m.dust-.5)*R*.1, by, sz*.5, sz*.9); } }
blendMode(BLEND); pop();

// star chart grid (abstracted style only)
if (st.chart) { push(); translate(poleX, poleY); rotate(rot); noFill(); stroke(hu(st.star[0]+ho), 60, 60, 16); strokeWeight(u*.0015); for (let ri = 1; ri <= 6; ri++) ellipse(0, 0, R*ri/6*2, R*ri/6*2); for (let ai = 0; ai < 12; ai++) { const a = ai/12*6.2832; line(0, 0, Math.cos(a)*R, Math.sin(a)*R); } pop(); }

// stars, wheeling about the pole with slow twinkle (no strobe)
const starC = [hu(st.star[0]+ho), st.star[1], st.star[2]];
push(); translate(poleX, poleY); rotate(rot);
blendMode(st.ink?BLEND:ADD);
for (let i = 0; i < S.stars.length; i++) { const s2 = S.stars[i]; const x = Math.cos(s2.th)*s2.rr*R, y = Math.sin(s2.th)*s2.rr*R; const tw = 0.72 + 0.28*Math.sin(K.t*(.35+s2.tw*.6)*P.speed + s2.ph); const br = (0.25 + s2.mag*0.95) * (0.4+en*0.8) * tw; const sz = u*(.001 + s2.mag*.006)*P.scale; if (st.chart) { noFill(); stroke(starC[0], starC[1], starC[2], 60*br); strokeWeight(u*.0012); ellipse(x, y, sz*2.4, sz*2.4); } else { fill(starC[0], starC[1]*(1-s2.mag*.4), starC[2], 90*br); ellipse(x, y, sz*2, sz*2); if (s2.mag > .6) { fill(starC[0], starC[1]*.3, starC[2], 30*br); ellipse(x, y, sz*5, sz*5); } } }
blendMode(BLEND); pop();

// a slow meteor now and then (subtle, low contrast)
const mCyc = (K.t*.05) % 6; if (mCyc < 1 && !st.chart) { const life = mCyc; const mx = width*(.2+fr(Math.floor(K.t*.05)*3)*.6) + life*width*.2; const my = ridgeY*(.2+fr(Math.floor(K.t*.05)*3+1)*.4) + life*height*.15; blendMode(ADD); stroke(starC[0], 20, 100, 40*(1-life)*en); strokeWeight(u*.002); line(mx, my, mx-u*.06, my-u*.045); blendMode(BLEND); noStroke(); }

// ---------------- ridge + observatory domes (foreground silhouette) ----------------
const domeC = [hu(st.dome[0]+ho), st.dome[1], st.dome[2]];
noStroke(); fill(domeC[0], domeC[1], domeC[2], 100);
beginShape(); vertex(0, height); vertex(0, ridgeY + u*.02*Math.sin(0));
for (let x = 0; x <= width; x += u*.03) { const n = Math.sin(x*.004 + fr(3)*6)*u*.012 + Math.sin(x*.011+fr(4)*6)*u*.006; vertex(x, ridgeY + n); }
vertex(width, height); endShape(CLOSE);
// domes on the ridge
const domes = [{dx:.3, r:.09, slit:1}, {dx:.56, r:.065, slit:0}, {dx:.14, r:.045, slit:0}];
for (let d = 0; d < domes.length; d++) { const dm = domes[d]; const cx = width*dm.dx, r = u*dm.r*P.scale, baseY = ridgeY - u*.005; fill(domeC[0], domeC[1], domeC[2]*.9, 100); rect(cx - r*1.05, baseY - r*.5, r*2.1, r*.6); arc(cx, baseY - r*.5, r*2.1, r*2.1, Math.PI, 0, CHORD); // dome slit glow
  if (dm.slit) { const gl = (0.5+0.5*Math.sin(K.t*.5))*P.glow; blendMode(ADD); stroke(st.ink?30:8, st.ink?20:80, 100, 30*gl*en); strokeWeight(r*.08); line(cx, baseY - r*.5, cx + r*.1, baseY - r*1.4); blendMode(BLEND); noStroke(); }
}
// faint light-pollution dome on the pole side
blendMode(ADD); for (let i = 0; i < 3; i++) { fill(hu(st.air[0]+ho), st.air[1], st.air[2], 4*P.glow*(1-i*.2)); ellipse(width*P.x, ridgeY, width*(.4+i*.2), u*(.2+i*.15)); } blendMode(BLEND);

if (P.alpha < 100) { fill(zen[0], zen[1]*.6, 3, (100-P.alpha)); rect(0,0,width,height); }
drawingContext.shadowBlur = 0;
